import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.DZhUhjDB.js";const m=JSON.parse('{"title":"🛡️ Ruta: Defensor (Blue Team)","description":"","frontmatter":{"title":"🛡️ Ruta: Defensor (Blue Team)"},"headers":[],"relativePath":"modules/fundamentos/rutas/ruta-defensor.md","filePath":"modules/fundamentos/rutas/ruta-defensor.md","lastUpdated":1787529976000}'),n={name:"modules/fundamentos/rutas/ruta-defensor.md"};function s(d,e,i,l,c,u){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="🛡️-ruta-defensor-blue-team" tabindex="-1">🛡️ Ruta: Defensor (Blue Team)</h1><blockquote><p><strong>Para quién es esto:</strong> gente que disfruta encontrar al malo, mirar logs, configurar detecciones y responder a incidentes. No te gusta destruir, te gusta proteger.</p></blockquote><h2 id="mentalidad" tabindex="-1">Mentalidad</h2><blockquote><p>&quot;Los atacantes tienen que acertar UNA vez. Yo tengo que acertar SIEMPRE.&quot;</p></blockquote><p>Eso suena injusto, pero también significa que tu trabajo se nota cuando funciona (nada se rompe) y se nota MUCHO cuando no funciona (algo se rompe enorme). Por eso defender bien es difícil y por eso se paga bien.</p><h2 id="paso-1-—-refuerza-la-base" tabindex="-1">Paso 1 — Refuerza la base</h2><p>Si vienes de <a href="./../01-que-es-ciberseguridad"><code>../01-que-es-ciberseguridad.md</code></a>, ya sabes que Blue Team tiene roles como:</p><ul><li>Analista SOC</li><li>Threat Hunter</li><li>Incident Responder</li><li>Threat Intelligence</li><li>Forense</li><li>Malware Analyst</li></ul><p>Lee sus definiciones en <a href="./../../01-CIBERSEGURIDAD/"><code>../../01-CIBERSEGURIDAD/</code></a> (busca las subcarpetas con esos nombres).</p><h2 id="paso-2-—-aprende-lo-tecnico-defensivo" tabindex="-1">Paso 2 — Aprende lo técnico defensivo</h2><h3 id="redes-lo-mas-importante" tabindex="-1">Redes (lo más importante)</h3><ul><li>Lee <a href="./../03-internet-y-redes"><code>../03-internet-y-redes.md</code></a> si aún no lo hiciste.</li><li>Aprende a leer PCAPs con Wireshark.</li><li>Entiende cómo se mueve un atacante lateralmente.</li></ul><h3 id="logs-donde-vive-la-verdad" tabindex="-1">Logs (donde vive la verdad)</h3><ul><li><a href="./../04-sistema-operativo-y-terminal"><code>../04-sistema-operativo-y-terminal.md</code></a> tiene las ubicaciones de logs en Linux y los Event IDs clave en Windows.</li><li>Practica filtrar: <code>grep</code>, <code>awk</code>, <code>jq</code>, Splunk Search Processing Language (SPL).</li></ul><h3 id="herramientas" tabindex="-1">Herramientas</h3><ul><li>Wazuh / OSSEC — HIDS</li><li>Splunk / ELK — SIEM</li><li>Velociraptor — endpoint DFIR</li><li>MISP / OpenCTI — Threat Intel</li></ul><h2 id="paso-3-—-recorre-las-carpetas-del-repo-relevantes" tabindex="-1">Paso 3 — Recorre las carpetas del repo relevantes</h2><p>En orden sugerido:</p><table tabindex="0"><thead><tr><th>Carpeta</th><th>Qué aporta</th></tr></thead><tbody><tr><td><a href="./../../03-blue-team-defensa/"><code>../../03-blue-team-defensa/</code></a></td><td>Punto de entrada Blue Team con labs específicos</td></tr><tr><td><a href="./../../03-blue-team-defensa/01-fundamentos-blue-team-y-soc/"><code>../../03-blue-team-defensa/01-fundamentos-blue-team-y-soc/</code></a></td><td>SOC fundamentals + labs de logs</td></tr><tr><td><a href="./../../02-SEGURIDAD-INFORMACION/02-blue-team-defensa/"><code>../../02-SEGURIDAD-INFORMACION/02-blue-team-defensa/</code></a></td><td>SIEM Wazuh, threat hunting, MITRE D3FEND</td></tr><tr><td><a href="./../../01-CIBERSEGURIDAD/seguridad-defensiva-blue-team/"><code>../../01-CIBERSEGURIDAD/seguridad-defensiva-blue-team/</code></a></td><td>Hardening, casos de uso, herramientas</td></tr><tr><td><a href="./../../01-CIBERSEGURIDAD/analista-soc/"><code>../../01-CIBERSEGURIDAD/analista-soc/</code></a></td><td>Vista de un analista SOC</td></tr><tr><td><a href="./../../01-CIBERSEGURIDAD/threat-hunter/"><code>../../01-CIBERSEGURIDAD/threat-hunter/</code></a></td><td>Hunting proactivo</td></tr><tr><td><a href="./../../01-CIBERSEGURIDAD/incident-responder/"><code>../../01-CIBERSEGURIDAD/incident-responder/</code></a></td><td>Pasos de respuesta a incidentes</td></tr><tr><td><a href="./../../01-CIBERSEGURIDAD/malware-analyst/"><code>../../01-CIBERSEGURIDAD/malware-analyst/</code></a></td><td>Análisis reversible</td></tr><tr><td><a href="./../../01-CIBERSEGURIDAD/forense-digital/"><code>../../01-CIBERSEGURIDAD/forense-digital/</code></a></td><td>Forensia digital</td></tr><tr><td><a href="./../../01-CIBERSEGURIDAD/security-analyst/"><code>../../01-CIBERSEGURIDAD/security-analyst/</code></a></td><td>Rol generalista</td></tr><tr><td><a href="./../../04-purple-team-colaboracion/"><code>../../04-purple-team-colaboracion/</code></a></td><td>Colaboración con red team</td></tr></tbody></table><h2 id="paso-4-—-practica-con-labs" tabindex="-1">Paso 4 — Practica con labs</h2><table tabindex="0"><thead><tr><th>Lab</th><th>Para qué</th></tr></thead><tbody><tr><td><a href="./../../04-LABORATORIOS/labs-propios/"><code>../../04-LABORATORIOS/labs-propios/</code></a></td><td>Labs diseñados por este repo</td></tr><tr><td><a href="./../../03-blue-team-defensa/01-fundamentos-blue-team-y-soc/laboratorios/"><code>../../02-blue-team-defensa/01-fundamentos-blue-team-y-soc/laboratorios/</code></a></td><td>Lectura interpretación logs SOC</td></tr><tr><td>TryHackMe SOC path</td><td><a href="https://tryhackme.com/" target="_blank" rel="noreferrer">tryhackme.com/path/outline/soc</a></td></tr><tr><td>Blue Team Labs Online</td><td><a href="https://blueteamlabs.online/" target="_blank" rel="noreferrer">blueteamlabs.online</a></td></tr></tbody></table><h2 id="paso-5-—-aprende-el-marco-mitre" tabindex="-1">Paso 5 — Aprende el marco MITRE</h2><ul><li><strong>MITRE ATT&amp;CK</strong> — cómo piensa y actúa un atacante</li><li><strong>MITRE D3FEND</strong> — técnicas defensivas para contrarrestar</li><li><strong>MITRE Caldera</strong> — emular atacantes en tu entorno</li></ul><p>Útil: lee <a href="./../../01-CIBERSEGURIDAD/threat-intelligence/"><code>../../01-CIBERSEGURIDAD/threat-intelligence/</code></a> para Threat Intel básico.</p><h2 id="paso-6-—-certificaciones-opcional-pero-util" tabindex="-1">Paso 6 — Certificaciones (opcional pero útil)</h2><p>Orden sugerido:</p><ol><li><strong>BTL1</strong> (Blue Team Level 1) —基础的, excelente para empezar.</li><li><strong>CompTIA Security+</strong> — base general.</li><li><strong>SC-200</strong> (Microsoft Security Operations Analyst) — Azure + Sentinel.</li><li><strong>GCIH</strong> (GIAC Certified Incident Handler) — respuesta a incidentes.</li><li><strong>GCFA</strong> (GIAC Certified Forensic Analyst) — forense.</li><li><strong>CISSP</strong> — cuando tengas experiencia.</li></ol><p>Más recursos en <a href="./../../05-RECURSOS/certificaciones/"><code>../../05-RECURSOS/certificaciones/</code></a>.</p><h2 id="paso-7-—-haz-home-labs-reales" tabindex="-1">Paso 7 — Haz &quot;home labs&quot; reales</h2><ul><li>Monta un SIEM casero (ELK o Wazuh + VMs).</li><li>Levanta un endpoint y prueba detecciones.</li><li>Genera tráfico malicioso controlado y mira qué loggea.</li><li>Escribe detecciones propias y mide falsos positivos.</li></ul><h2 id="✏️-plan-de-30-dias-para-empezar" tabindex="-1">✏️ Plan de 30 días para empezar</h2><ul><li><strong>Semana 1:</strong> relee <a href="./../02-glosario"><code>../02-glosario.md</code></a> y abre <a href="./../../03-blue-team-defensa/"><code>../../03-blue-team-defensa/</code></a>.</li><li><strong>Semana 2:</strong> completa 2 labs en <a href="./../../03-blue-team-defensa/01-fundamentos-blue-team-y-soc/laboratorios/"><code>../../03-blue-team-defensa/01-fundamentos-blue-team-y-soc/laboratorios/</code></a>.</li><li><strong>Semana 3:</strong> monta Wazuh o ELK en tu VM y configura detección básica.</li><li><strong>Semana 4:</strong> lee todo lo de <a href="./../../02-SEGURIDAD-INFORMACION/02-blue-team-defensa/"><code>../../02-SEGURIDAD-INFORMACION/02-blue-team-defensa/</code></a> y elige una de las áreas (SOC, hunting, forense) para profundizar.</li></ul><blockquote><p>🟣 <strong>Bonus:</strong> si haces Red Team además de Blue Team, mira <a href="./../../04-purple-team-colaboracion/"><code>../../04-purple-team-colaboracion/</code></a>. El perfil completo Blue+Red es muy buscado.</p></blockquote><hr><blockquote><p>⏪ <strong>Volver al mapa:</strong> <a href="./../09-como-seguir-este-repo"><code>../09-como-seguir-este-repo.md</code></a> ⚔️ <strong>Otra ruta:</strong> <a href="./ruta-atacante"><code>./ruta-atacante.md</code></a> si te interesa el lado ofensivo.</p></blockquote>',35)])])}const f=a(n,[["render",s]]);export{m as __pageData,f as default};
